def _rule_to_instant(month, week, weekday, hour, minute, year, offset):
    d = 1 + (weekday - date(year, month, 1).weekday()) % 7
    if week > 0:
        d += (week - 1) * 7
    else:
        if month == 12:
            nm, ny = 1, year + 1
        else:
            nm, ny = month + 1, year
        d_next = 1 + (weekday - date(ny, nm, 1).weekday()) % 7
        d = d_next - 7
    dt = datetime(year, month, d, hour, minute)
    epoch = datetime(1970, 1, 1)
    local_min = (dt - epoch).days * 1440 + hour * 60 + minute
    return local_min - offset

