import calendar

def _validate_zone(zone):
    if not isinstance(zone, dict):
        raise ValueError("zone must be a dict")
    if "std" not in zone or "dst" not in zone:
        raise ValueError("zone must have 'std' and 'dst'")
    std = zone["std"]
    if not isinstance(std, int) or not (-900 <= std <= 900):
        raise ValueError("std out of range")
    dst = zone["dst"]
    if dst is not None:
        if not isinstance(dst, dict):
            raise ValueError("dst must be None or dict")
        if "save" not in dst or "start" not in dst or "end" not in dst:
            raise ValueError("dst missing keys")
        save = dst["save"]
        if not isinstance(save, int) or not (1 <= save <= 180):
            raise ValueError("save out of range")
        for key in ("start", "end"):
            rule = dst[key]
            if not (isinstance(rule, (list, tuple)) and len(rule) == 5):
                raise ValueError(f"{key} must be sequence of 5 ints")
            mo, wk, wd, h, mi = rule
            if not all(isinstance(x, int) for x in rule):
                raise ValueError(f"{key} fields must be ints")
            if not (1 <= mo <= 12): raise ValueError("month out of range")
            if not (-1 <= wk <= 4) or (wk != -1 and wk < 1): raise ValueError("week out of range")
            if not (0 <= wd <= 6): raise ValueError("weekday out of range")
            if not (0 <= h <= 23): raise ValueError("hour out of range")
            if not (0 <= mi <= 59): raise ValueError("minute out of range")
        if dst["start"][0] == dst["end"][0]:
            raise ValueError("start and end months must differ")

def _rule_to_day(mo, wk, wd, year):
    first = datetime.date(year, mo, 1)
    first_wd = first.weekday()
    days_to_first = (wd - first_wd) % 7
    if wk == -1:
        last_date = datetime.date(year, mo, calendar.monthrange(year, mo)[1])
        last_wd = last_date.weekday()
        days_from_last = (last_wd - wd) % 7
        return last_date.day - days_from_last
    else:
        return 1 + days_to_first + (wk - 1) * 7

def _local_to_utc_naive(y, mo, d, h, mi, offset):
    dt = datetime.datetime(y, mo, d, h, mi)
    utc_dt = dt - datetime.timedelta(minutes=offset)
    epoch = datetime.datetime(1970, 1, 1)
    return int((utc_dt - epoch).total_seconds() / 60)

def _get_transitions(zone, y):
    std = zone["std"]
    dst = zone["dst"]
    if dst is None:
        return []
    save = dst["save"]
    start_r = dst["start"]
    end_r = dst["end"]
    start_mo = start_r[0]
    end_mo = end_r[0]

    start_day = _rule_to_day(start_mo, start_r[1], start_r[2], y)
    start_utc = _local_to_utc_naive(y, start_mo, start_day, start_r[3], start_r[4], std)

    end_day = _rule_to_day(end_mo, end_r[1], end_r[2], y)
    end_utc = _local_to_utc_naive(y, end_mo, end_day, end_r[3], end_r[4], std + save)

    if start_mo > end_mo:
        end_day_next = _rule_to_day(end_mo, end_r[1], end_r[2], y + 1)
        end_utc_next = _local_to_utc_naive(y + 1, end_mo, end_day_next, end_r[3], end_r[4], std + save)
        return [(start_utc, std + save), (end_utc_next, std)]
    else:
        return [(start_utc, std + save), (end_utc, std)]

def local_to_utc(zone, y, mo, d, h, mi, fold=0):
    _validate_zone(zone)
    if not isinstance(y, int) or not (1970 <= y <= 2100): raise ValueError("y out of range")
    if not isinstance(mo, int) or not (1 <= mo <= 12): raise ValueError("mo out of range")
    if not isinstance(d, int) or not (1 <= d <= 31): raise ValueError("d out of range")
    if not isinstance(h, int) or not (0 <= h <= 23): raise ValueError("h out of range")
    if not isinstance(mi, int) or not (0 <= mi <= 59): raise ValueError("mi out of range")
    if fold not in (0, 1): raise ValueError("fold must be 0 or 1")
    try:
        datetime.date(y, mo, d)
    except ValueError:
        raise ValueError("invalid date")

    std = zone["std"]
    dst = zone["dst"]
    if dst is None:
        return _local_to_utc_naive(y, mo, d, h, mi, std)

    save = dst["save"]
    L_min = _local_to_utc_naive(y, mo, d, h, mi, 0)
    utc_dst = L_min - (std + save)
    utc_std = L_min - std

    # Get transitions for year y and y+1 to cover southern hemisphere wrap
    trans = _get_transitions(zone, y) + _get_transitions(zone, y + 1)
    if not trans:
        return utc_std

    dst_start = min(t[0] for t in trans)
    dst_end = max(t[0] for t in trans)

    in_dst_dst = dst_start <= utc_dst < dst_end
    in_std = utc_std < dst_start or utc_std >= dst_end

    if in_dst_dst and in_std:
        return utc_dst if fold == 0 else utc_std
    if in_dst_dst:
        return utc_dst
    if in_std:
        return utc_std
    raise ValueError("wall time does not exist")

def next_transition(zone, t):
    _validate_zone(zone)
    dst = zone["dst"]
    if dst is None:
        return None

    # Estimate year range to cover transitions around t
    t_year = 1970 + t // 525960
    y_min = max(1970, t_year - 2)
    y_max = t_year + 3

    candidates = []
    for y in range(y_min, y_max + 1):
        candidates.extend(_get_transitions(zone, y))

    # Filter strictly after t, pick smallest
    after = [tr for tr in candidates if tr[0] > t]
    if not after:
        return None
    after.sort(key=lambda x: x[0])
    return after[0]

