def _rule_to_utc(rule, year, offset):
    m, w, wd, h, mi = rule
    first = date(year, m, 1)
    first_wd = first.weekday()
    # Find first occurrence of weekday in month
    d = (wd - first_wd) % 7
    if w == -1:
        # Last occurrence: find first in next month, go back
        nm = m + 1 if m < 12 else 1
        ny = year if m < 12 else year + 1
        nfirst = date(ny, nm, 1)
        d = (wd - nfirst.weekday()) % 7
        d = 7 - d if d != 0 else 7
        d += 28  # Add 4 weeks
        # Adjust back to correct month
        while date(year, m, d).month != m:
            d -= 7
    else:
        d += (w - 1) * 7
    dt = datetime(year, m, d, h, mi)
    utc_dt = dt - timedelta(minutes=offset)
    epoch = datetime(1970, 1, 1)
    return int((utc_dt - epoch).total_seconds() // 60)

