def _get_last_day(year, month):
    if month == 12:
        next_month = date(year + 1, 1, 1)
    else:
        next_month = date(year, month + 1, 1)
    return (next_month - timedelta(days=1)).day

def _rule_to_utc(rule, year, offset):
    m, w, wd, h, mi = rule

    # Find first occurrence of weekday in month
    first = date(year, m, 1)
    first_wd = first.weekday()
    d_first = 1 + (wd - first_wd) % 7

    if w == -1:
        # Last occurrence
        last_day = _get_last_day(year, m)
        # Find largest d = d_first + 7*k <= last_day
        k = (last_day - d_first) // 7
        d = d_first + 7 * k
    else:
        # w is 1..4
        d = d_first + (w - 1) * 7

    # Validate date
    try:
        dt = datetime(year, m, d, h, mi)
    except ValueError:
        raise ValueError(f"Invalid rule date: {year}-{m}-{d}")

    utc_dt = dt - timedelta(minutes=offset)
    epoch = datetime(1970, 1, 1)
    return int((utc_dt - epoch).total_seconds() // 60)

def local_to_utc(zone, y, mo, d, h, mi, fold=0):
    _validate_zone(zone)
    if not isinstance(y, int) or isinstance(y, bool) or not (1970 <= y <= 2100):
        raise ValueError("y must be int in 1970..2100")
    if not isinstance(mo, int) or not (1 <= mo <= 12):
        raise ValueError("mo must be int in 1..12")
    if not isinstance(d, int) or d < 1:
        raise ValueError("d must be positive int")
    if not isinstance(h, int) or not (0 <= h <= 23):
        raise ValueError("h must be int in 0..23")
    if not isinstance(mi, int) or not (0 <= mi <= 59):
        raise ValueError("mi must be int in 0..59")
    if fold not in (0, 1):
        raise ValueError("fold must be 0 or 1")
    try:
        datetime(y, mo, d, h, mi)
    except ValueError:
        raise ValueError("invalid date")

    std = zone["std"]
    dst = zone["dst"]
    if dst is None:
        # No DST, just apply standard offset
        dt = datetime(y, mo, d, h, mi)
        utc_dt = dt - timedelta(minutes=std)
        epoch = datetime(1970, 1, 1)
        return int((utc_dt - epoch).total_seconds() // 60)

    save = dst["save"]
    start_rule = dst["start"]
    end_rule = dst["end"]
    sm = start_rule[0]
    em = end_rule[0]

    # Compute transition instants for year y
    # Start rule uses std offset
    S = _rule_to_utc(start_rule, y, std)

    # End rule uses dst offset (std + save)
    if sm < em:
        # Northern hemisphere: ends in same year
        E = _rule_to_utc(end_rule, y, std + save)
    else:
        # Southern hemisphere: ends in next year
        E = _rule_to_utc(end_rule, y + 1, std + save)

    # Calculate UTC instants assuming standard and DST offsets
    # t_std assumes local time is in standard time (offset std)
    dt_std = datetime(y, mo, d, h, mi)
    utc_std_dt = dt_std - timedelta(minutes=std)
    epoch = datetime(1970, 1, 1)
    t_std = int((utc_std_dt - epoch).total_seconds() // 60)

    # t_dst assumes local time is in daylight time (offset std + save)
    t_dst = t_std - save

    # Check for skipped time (Spring Forward)
    # Skipped if t_std falls in [S, S + save)
    if S <= t_std < S + save:
        raise ValueError("wall time skipped")

    # Check for ambiguous time (Fall Back)
    # Ambiguous if t_std falls in [E, E + save]
    if E <= t_std <= E + save:
        # fold 0 -> first occurrence (DST) -> t_dst
        # fold 1 -> second occurrence (STD) -> t_std
        return t_dst if fold == 0 else t_std

    # Determine if DST is active
    # DST is active between S and E.
    # In UTC, this is [S, E).
    # If t_std is in [S, E), then DST is active.
    # If DST active, return t_dst.
    # If STD active, return t_std.

    if S <= t_std < E:
        return t_dst
    else:
        return t_std

def next_transition(zone, t):
    _validate_zone(zone)
    if not isinstance(t, int) or isinstance(t, bool):
        raise ValueError("t must be int")
    dst = zone["dst"]
    if dst is None:
        return None
    std = zone["std"]
    save = dst["save"]
    start_rule = dst["start"]
    end_rule = dst["end"]
    sm = start_rule[0]
    em = end_rule[0]

    # Estimate year of t to check surrounding years
    # Approx minutes per year ~ 525960 (365.25 * 24 * 60)
    approx_year = 1970 + t // 525960
    candidates = []

    # We need to find the first transition strictly after t.
    # Transitions happen at S (start of DST) and E (end of DST).
    # S is in year y, E is in year y (or y+1).
    # We check years around approx_year.

    for y in range(approx_year - 2, approx_year + 4):
        # Compute S for year y
        try:
            S = _rule_to_utc(start_rule, y, std)
        except ValueError:
            continue

        # Compute E
        if sm < em:
            # Northern: E in same year y
            try:
                E = _rule_to_utc(end_rule, y, std + save)
            except ValueError:
                continue
            # Transition at S: offset becomes std + save (DST)
            if S > t:
                candidates.append((S, std + save))
            # Transition at E: offset becomes std (STD)
            if E > t:
                candidates.append((E, std))
        else:
            # Southern: E in year y+1
            try:
                E = _rule_to_utc(end_rule, y + 1, std + save)
            except ValueError:
                continue
            # Transition at S (in y): offset becomes std + save
            if S > t:
                candidates.append((S, std + save))
            # Transition at E (in y+1): offset becomes std
            if E > t:
                candidates.append((E, std))

    if not candidates:
        return None

    candidates.sort()
    return candidates[0]

