        for v in (arr, burst, pri):
            if type(v) is bool or not isinstance(v, int):
                raise ValueError("Elements must be integers, not booleans")
        if arr < 0 or burst < 1:
            raise ValueError("arrival >= 0 and burst >= 1 required")

    if type(q) is bool or not isinstance(q, int) or q < 1:
        raise ValueError("q must be an integer >= 1")

    n = len(jobs)
    if n == 0:
        return []

    # Store original indices to return results in input order
    # indexed_jobs: (arrival, original_index, burst, priority)
    # Sort by arrival, then by original index to maintain input order for ties
    indexed_jobs = sorted(
        [(j[0], i, j[1], j[2]) for i, j in enumerate(jobs)], 
        key=lambda x: (x[0], x[1])
    )

    queues = collections.defaultdict(collections.deque)
    results = [None] * n
    running = None  # Dict: {'idx', 'rem', 'pri', 'start', 'q_used'}
    arr_idx = 0
    current_time = indexed_jobs[0][0]  # Start at first arrival

    while arr_idx < n or running is not None:
        t = current_time

        # 1. Completion
        if running is not None and running['rem'] == 0:
            results[running['idx']] = (running['start'], t)
            running = None

        # 2. Arrivals
        while arr_idx < n and indexed_jobs[arr_idx][0] == t:
            _, i, b, p = indexed_jobs[arr_idx]
            queues[p].append(i)
            arr_idx += 1

        # 3. Preemption / Quantum
        if running is not None:
            if running['q_used'] == q:
                # Quantum expired, go to back of queue
                queues[running['pri']].append(running['idx'])
                running = None
            else:
                # Quantum not expired. Check for strictly better priority waiting.
                has_better = False
                for p in queues:
                    if queues[p] and p < running['pri']:
                        has_better = True
                        break

                if has_better:
                    # Preempt running job to FRONT of its queue
                    queues[running['pri']].appendleft(running['idx'])
                    running = None

        # 4. Start job
        if running is None:
            # Find best priority (smallest p) with non-empty queue
            best_p = None
            for p in queues:
                if queues[p]:
                    if best_p is None or p < best_p:
                        best_p = p

            if best_p is not None:
                # Pick first job from this queue (FIFO)
                i = queues[best_p].popleft()
                b = jobs[i][1]
                p = jobs[i][2]

                running = {
                    'idx': i,
                    'rem': b,
                    'pri': p,
                    'start': t,
                    'q_used': 0
                }

        # 5. Calculate next event time / Advance time
        if running is not None and running['rem'] > 0:
            # Determine max time this job can run in current quantum
            time_left_in_quantum = q - running['q_used']
            max_run = min(running['rem'], time_left_in_quantum)

            # Check if a better priority job arrives before max_run
            next_better_arrival = float('inf')

            # indexed_jobs is sorted by arrival. arr_idx points to next unarrived job.
            for k in range(arr_idx, n):
                at, _, _, ap = indexed_jobs[k]
                if ap < running['pri']:
                    next_better_arrival = at
                    break

            # Determine actual duration to run
            if next_better_arrival != float('inf') and next_better_arrival < t + max_run:
                duration = next_better_arrival - t
                current_time = next_better_arrival
            else:
                duration = max_run
                current_time = t + duration

            # Update running job state
            running['rem'] -= duration
            running['q_used'] += duration

        else:
            # CPU is idle (running is None or finished and no jobs to start)
            if arr_idx < n:
                # Jump to next arrival
                current_time = indexed_jobs[arr_idx][0]
            else:
                # No more jobs and CPU idle. Done.
                break

    # If loop exits and running job is still active (should be finished by logic, but safety check)
    if running is not None:
        results[running['idx']] = (running['start'], current_time)

    return results

