class Type:
    __slots__ = ('kind', 'args')
    def __init__(self, kind, *args):
        self.kind = kind
        self.args = args
    def __eq__(self, other):
        return isinstance(other, Type) and self.kind == other.kind and self.args == other.args
    def __hash__(self):
        return hash((self.kind, self.args))

def apply_subs(t, subs):
    if t.kind == 'Var':
        return subs.get(t.args[0], t)
    return Type(t.kind, *[apply_subs(a, subs) for a in t.args])

def get_free_vars(t):
    res = set()
    def collect(tt):
        if tt.kind == 'Var':
            res.add(tt.args[0])
        else:
            for a in tt.args:
                collect(a)
    collect(t)
    return res

def get_env_free_vars(env, exclude=None):
    if exclude is None:
        exclude = set()
    res = set()
    for scope in env:
        for n, (ty, _) in scope.items():
            if n in exclude:
                continue
            def collect(tt):
                if tt.kind == 'Var':
                    res.add(tt.args[0])
                else:
                    for a in tt.args:
                        collect(a)
            collect(ty)
    return res

def gen(t, env, exclude=None):
    if exclude is None:
        exclude = set()
    free = get_free_vars(t)
    env_free = get_env_free_vars(env, exclude)
    quantified = free - env_free
    return (t, quantified)

def inst(poly, fresh):
    t, qs = poly
    subs = {}
    for v in qs:
        subs[v] = Type('Var', fresh.next())
    return apply_subs(t, subs)

def var_occurs(v, t, subs):
    t = apply_subs(t, subs)
    def check(tt):
        if tt.kind == 'Var':
            return tt.args[0] == v
        return any(check(a) for a in tt.args)
    return check(t)

def unify(t1, t2, subs):
    t1 = apply_subs(t1, subs)
    t2 = apply_subs(t2, subs)
    if t1 == t2:
        return subs
    if t1.kind == 'Var':
        if var_occurs(t1.args[0], t2, subs):
            raise ValueError("Occurs check")
        new_subs = dict(subs)
        new_subs[t1.args[0]] = t2
        return new_subs
    if t2.kind == 'Var':
        if var_occurs(t2.args[0], t1, subs):
            raise ValueError("Occurs check")
        new_subs = dict(subs)
        new_subs[t2.args[0]] = t1
        return new_subs
    if t1.kind != t2.kind:
        raise ValueError("Type mismatch")
    if t1.kind in ('Fun', 'Pair'):
        subs = unify(t1.args[0], t2.args[0], subs)
        subs = unify(t1.args[1], t2.args[1], subs)
        return subs
    raise ValueError("Type mismatch")

class FreshCounter:
    def __init__(self):
        self.val = 0
    def next(self):
        v = self.val
        self.val += 1
        return v

def infer_term(term, env, subs, fresh):
    if not isinstance(term, tuple):
        raise ValueError("Malformed term")
    if len(term) == 0:
        raise ValueError("Malformed term")

    tag = term[0]
    if tag == 'int':
        if len(term) != 2 or not isinstance(term[1], int):
            raise ValueError("Malformed term")
        return Type('Int')
    elif tag == 'bool':
        if len(term) != 2 or not isinstance(term[1], bool):
            raise ValueError("Malformed term")
        return Type('Bool')
    elif tag == 'var':
        if len(term) != 2 or not isinstance(term[1], str) or not term[1]:
            raise ValueError("Malformed term")
        name = term[1]
        for scope in reversed(env):
            if name in scope:
                poly = scope[name]
                t = inst(poly, fresh)
                return apply_subs(t, subs)
        raise ValueError("Unbound variable")
    elif tag == 'lam':
        if len(term) != 3 or not isinstance(term[1], str) or not term[1]:
            raise ValueError("Malformed term")
        name, body = term[1], term[2]
        v = fresh.next()
        arg_type = Type('Var', v)
        new_env = env + [{name: (arg_type, set())}]
        body_type = infer_term(body, new_env, subs, fresh)
        return Type('Fun', arg_type, body_type)
    elif tag == 'app':
        if len(term) != 3:
            raise ValueError("Malformed term")
        f, arg = term[1], term[2]
        f_type = infer_term(f, env, subs, fresh)
        arg_type = infer_term(arg, env, subs, fresh)
        ret_type = Type('Var', fresh.next())
        subs = unify(f_type, Type('Fun', arg_type, ret_type), subs)
        return apply_subs(ret_type, subs)
    elif tag == 'if':
        if len(term) != 4:
            raise ValueError("Malformed term")
        c, t, e = term[1], term[2], term[3]
        c_type = infer_term(c, env, subs, fresh)
        t_type = infer_term(t, env, subs, fresh)
        e_type = infer_term(e, env, subs, fresh)
        subs = unify(c_type, Type('Bool'), subs)
        subs = unify(t_type, e_type, subs)
        return apply_subs(t_type, subs)
    elif tag == 'pair':
        if len(term) != 3:
            raise ValueError("Malformed term")
        a, b = term[1], term[2]
        t1 = infer_term(a, env, subs, fresh)
        t2 = infer_term(b, env, subs, fresh)
        return Type('Pair', t1, t2)
    elif tag == 'fst':
        if len(term) != 2:
            raise ValueError("Malformed term")
        e = term[1]
        e_type = infer_term(e, env, subs, fresh)
        t1 = Type('Var', fresh.next())
        t2 = Type('Var', fresh.next())
        subs = unify(e_type, Type('Pair', t1, t2), subs)
        return apply_subs(t1, subs)
    elif tag == 'snd':
        if len(term) != 2:
            raise ValueError("Malformed term")
        e = term[1]
        e_type = infer_term(e, env, subs, fresh)
        t1 = Type('Var', fresh.next())
        t2 = Type('Var', fresh.next())
        subs = unify(e_type, Type('Pair', t1, t2), subs)
        return apply_subs(t2, subs)
    elif tag == 'let':
        if len(term) != 4:
            raise ValueError("Malformed term")
        name, e1, e2 = term[1], term[2], term[3]
        if not isinstance(name, str) or not name:
            raise ValueError("Malformed term")
        e1_type = infer_term(e1, env, subs, fresh)
        poly = gen(e1_type, env)
        new_env = env + [{name: poly}]
        e2_type = infer_term(e2, new_env, subs, fresh)
        return apply_subs(e2_type, subs)
    elif tag == 'letrec':
        if len(term) != 4:
            raise ValueError("Malformed term")
        name, e1, e2 = term[1], term[2], term[3]
        if not isinstance(name, str) or not name:
            raise ValueError("Malformed term")
        v = fresh.next()
        rec_type = Type('Var', v)
        new_env = env + [{name: (rec_type, set())}]
        e1_type = infer_term(e1, new_env, subs, fresh)
        subs = unify(rec_type, e1_type, subs)
        e1_type = apply_subs(e1_type, subs)
        poly = gen(e1_type, env, exclude={name})
        new_env[-1][name] = poly
        e2_type = infer_term(e2, new_env, subs, fresh)
        return apply_subs(e2_type, subs)
    else:
        raise ValueError("Malformed term")

def type_to_str(t, subs):
    t = apply_subs(t, subs)
    vars_in_order = []
    seen = set()

    def collect_vars(tt):
        if tt.kind == 'Var':
            if tt.args[0] not in seen:
                seen.add(tt.args[0])
                vars_in_order.append(tt.args[0])
        else:
            for a in tt.args:
                collect_vars(a)

    collect_vars(t)

    def var_name(v_id):
        idx = vars_in_order.index(v_id)
        if idx < 26:
            return chr(ord('a') + idx)
        else:
            q, r = divmod(idx - 26, 26)
            return chr(ord('a') + r) + str(q + 1)

    def print_tt(tt):
        if tt.kind == 'Var':
            return var_name(tt.args[0])
        elif tt.kind == 'Int':
            return 'Int'
        elif tt.kind == 'Bool':
            return 'Bool'
        elif tt.kind == 'Fun':
            left = print_tt(tt.args[0])
            right = print_tt(tt.args[1])
            if tt.args[0].kind == 'Fun':
                left = f"({left})"
            return f"{left} -> {right}"
        elif tt.kind == 'Pair':
            return f"({print_tt(tt.args[0])}, {print_tt(tt.args[1])})"
        return ''

    return print_tt(t)

def infer(term):
    fresh = FreshCounter()
    v1 = fresh.next()
    init_env = [{
        'add': (Type('Fun', Type('Fun', Type('Int'), Type('Int')), Type('Int')), set()),
        'eq': (Type('Fun', Type('Fun', Type('Var', v1), Type('Var', v1)), Type('Bool')), {v1}),
        'not': (Type('Fun', Type('Bool'), Type('Bool')), set())
    }]
    subs = {}
    res_type = infer_term(term, init_env, subs, fresh)
    return type_to_str(res_type, subs)

class Type:
    __slots__ = ('kind', 'args')
    def __init__(self, kind, *args):
        self.kind = kind
        self.args = args
    def __eq__(self, other):
        return isinstance(other, Type) and self.kind == other.kind and self.args == other.args
    def __hash__(self):
        return hash((self.kind, self.args))

def apply_subs(t, subs):
    if t.kind == 'Var':
        res = subs.get(t.args[0], t)
        if res != t:
            return apply_subs(res, subs)
        return t
    return Type(t.kind, *[apply_subs(a, subs) for a in t.args])

def var_in(id, t, subs):
    t = apply_subs(t, subs)
    def check(tt):
        if tt.kind == 'Var':
            return tt.args[0] == id
        return any(check(a) for a in tt.args)
    return check(t)

def unify(t1, t2, subs):
    t1 = apply_subs(t1, subs)
    t2 = apply_subs(t2, subs)
    if t1 == t2:
        return subs
    if t1.kind == 'Var':
        if var_in(t1.args[0], t2, subs):
            raise ValueError("Occurs check")
        subs[t1.args[0]] = t2
        return subs
    if t2.kind == 'Var':
        if var_in(t2.args[0], t1, subs):
            raise ValueError("Occurs check")
        subs[t2.args[0]] = t1
        return subs
    if t1.kind != t2.kind:
        raise ValueError("Type mismatch")
    if t1.kind in ('Fun', 'Pair'):
        subs = unify(t1.args[0], t2.args[0], subs)
        subs = unify(t1.args[1], t2.args[1], subs)
        return subs
    raise ValueError("Type mismatch")

def get_free_vars(t):
    res = set()
    def collect(tt):
        if tt.kind == 'Var':
            res.add(tt.args[0])
        else:
            for a in tt.args:
                collect(a)
    collect(t)
    return res

def get_free_vars_env(env):
    res = set()
    for scope in env:
        for _, (ty, _) in scope.items():
            def collect(tt):
                if tt.kind == 'Var':
                    res.add(tt.args[0])
                else:
                    for a in tt.args:
                        collect(a)
            collect(ty)
    return res

class State:
    def __init__(self):
        self.subs = {}
        self.fresh_id = 0
        self.env = [{}]
        v1, v2 = self.fresh(), self.fresh()
        self.env[0]['add'] = (Type('Fun', Type('Fun', Type('Int'), Type('Int')), Type('Int')), set())
        self.env[0]['eq'] = (Type('Fun', Type('Fun', Type('Var', v1), Type('Var', v1)), Type('Bool')), set())
        self.env[0]['not'] = (Type('Fun', Type('Bool'), Type('Bool')), set())

    def fresh(self):
        v = self.fresh_id
        self.fresh_id += 1
        return v

def gen(t, env):
    free_t = get_free_vars(t)
    free_env = get_free_vars_env(env)
    quantified = free_t - free_env
    return (t, quantified)

def inst(poly, state):
    t, quantified = poly
    new_subs = {}
    for v in quantified:
        new_subs[v] = Type('Var', state.fresh())
    return apply_subs(t, new_subs)

