    free_env = get_free_vars_env(env)
    quantified = free_t - free_env
    return (t, quantified)

def inst(poly, state):
    t, quantified = poly
    new_subs = {}
    for v in quantified:
        new_subs[v] = Type('Var', state.fresh())
    return apply_subs(t, new_subs)

def infer_term(term, state):
    if not isinstance(term, tuple):
        raise ValueError("Malformed term")
    if len(term) == 0:
        raise ValueError("Malformed term")

    tag = term[0]
    if tag == 'int':
        if len(term) != 2 or type(term[1]) is not int:
            raise ValueError("Malformed term")
        return Type('Int')
    elif tag == 'bool':
        if len(term) != 2 or type(term[1]) is not bool:
            raise ValueError("Malformed term")
        return Type('Bool')
    elif tag == 'var':
        if len(term) != 2 or not isinstance(term[1], str) or not term[1]:
            raise ValueError("Malformed term")
        name = term[1]
        for scope in reversed(state.env):
            if name in scope:
                res = inst(scope[name], state)
                return apply_subs(res, state.subs)
        raise ValueError("Unbound variable")
    elif tag == 'lam':
        if len(term) != 3 or not isinstance(term[1], str) or not term[1]:
            raise ValueError("Malformed term")
        name, body = term[1], term[2]
        v = state.fresh()
        arg_type = Type('Var', v)
        state.env.append({name: (arg_type, set())})
        body_type = infer_term(body, state)
        state.env.pop()
        return Type('Fun', arg_type, body_type)
    elif tag == 'app':
        if len(term) != 3:
            raise ValueError("Malformed term")
        f, arg = term[1], term[2]
        f_type = infer_term(f, state)
        arg_type = infer_term(arg, state)
        ret_type = Type('Var', state.fresh())
        state.subs = unify(f_type, Type('Fun', arg_type, ret_type), state.subs)
        return apply_subs(ret_type, state.subs)
    elif tag == 'if':
        if len(term) != 4:
            raise ValueError("Malformed term")
        c, t, e = term[1], term[2], term[3]
        c_type = infer_term(c, state)
        t_type = infer_term(t, state)
        e_type = infer_term(e, state)
        state.subs = unify(c_type, Type('Bool'), state.subs)
        state.subs = unify(t_type, e_type, state.subs)
        return apply_subs(t_type, state.subs)
    elif tag == 'pair':
        if len(term) != 3:
            raise ValueError("Malformed term")
        a, b = term[1], term[2]
        return Type('Pair', infer_term(a, state), infer_term(b, state))
    elif tag == 'fst':
        if len(term) != 2:
            raise ValueError("Malformed term")
        e = term[1]
        e_type = infer_term(e, state)
        t1 = Type('Var', state.fresh())
        t2 = Type('Var', state.fresh())
        state.subs = unify(e_type, Type('Pair', t1, t2), state.subs)
        return apply_subs(t1, state.subs)
    elif tag == 'snd':
        if len(term) != 2:
            raise ValueError("Malformed term")
        e = term[1]
        e_type = infer_term(e, state)
        t1 = Type('Var', state.fresh())
        t2 = Type('Var', state.fresh())
        state.subs = unify(e_type, Type('Pair', t1, t2), state.subs)
        return apply_subs(t2, state.subs)
    elif tag == 'let':
        if len(term) != 4:
            raise ValueError("Malformed term")
        name, e1, e2 = term[1], term[2], term[3]
        if not isinstance(name, str) or not name:
            raise ValueError("Malformed term")
        e1_type = infer_term(e1, state)
        e1_type = apply_subs(e1_type, state.subs)
        poly = gen(e1_type, state.env)
        state.env.append({name: poly})
        e2_type = infer_term(e2, state)
        state.env.pop()
        return apply_subs(e2_type, state.subs)
    elif tag == 'letrec':
        if len(term) != 4:
            raise ValueError("Malformed term")
        name, e1, e2 = term[1], term[2], term[3]
        if not isinstance(name, str) or not name:
            raise ValueError("Malformed term")
        v = state.fresh()
        rec_type = Type('Var', v)
        state.env.append({name: (rec_type, set())})
        e1_type = infer_term(e1, state)
        state.subs = unify(rec_type, e1_type, state.subs)
        e1_type = apply_subs(e1_type, state.subs)
        poly = gen(e1_type, state.env)
        state.env[-1][name] = poly
        e2_type = infer_term(e2, state)
        state.env.pop()
        return apply_subs(e2_type, state.subs)
    else:
        raise ValueError("Malformed term")

def type_to_str(t, subs):
    t = apply_subs(t, subs)
    seen = []
    seen_set = set()
    def collect(tt):
        if tt.kind == 'Var':
            if tt.args[0] not in seen_set:
                seen.append(tt.args[0])
                seen_set.add(tt.args[0])
        else:
            for a in tt.args:
                collect(a)
    collect(t)

    names = []
    for i in range(len(seen)):
        if i < 26:
            names.append(chr(ord('a') + i))
        else:
            q, r = divmod(i - 26, 26)
            names.append(chr(ord('a') + r) + str(q + 1))
    var_map = {v: names[i] for i, v in enumerate(seen)}

    def print_tt(tt):
        if tt.kind == 'Var':
            return var_map[tt.args[0]]
        elif tt.kind == 'Int':
            return 'Int'
        elif tt.kind == 'Bool':
            return 'Bool'
        elif tt.kind == 'Fun':
            left = print_tt(tt.args[0])
            right = print_tt(tt.args[1])
            if tt.args[0].kind == 'Fun':
                left = f"({left})"
            return f"{left} -> {right}"
        elif tt.kind == 'Pair':
            return f"({print_tt(tt.args[0])}, {print_tt(tt.args[1])})"
        return ''
    return print_tt(t)

def infer(term):
    state = State()
    res_type = infer_term(term, state)
    return type_to_str(res_type, state.subs)

def phi_blocks(n, edges, entry, defs):
    # Input validation
    if not isinstance(n, int) or isinstance(n, bool) or n < 1:
        raise ValueError("n must be an int >= 1")
    if not isinstance(entry, int) or isinstance(entry, bool) or not (0 <= entry < n):
        raise ValueError("entry must be an int in 0..n-1")
    if not isinstance(edges, list):
        raise ValueError("edges must be a list")
    for e in edges:
        if not isinstance(e, (list, tuple)) or len(e) != 2:
            raise ValueError("edges must be a list of pairs of ints in 0..n-1")
        if not isinstance(e[0], int) or isinstance(e[0], bool) or not (0 <= e[0] < n):
            raise ValueError("edges must be a list of pairs of ints in 0..n-1")
        if not isinstance(e[1], int) or isinstance(e[1], bool) or not (0 <= e[1] < n):
            raise ValueError("edges must be a list of pairs of ints in 0..n-1")
    if not isinstance(defs, dict):
        raise ValueError("defs must be a dict")
    for k, v in defs.items():
        try:
            v_iter = iter(v)
        except TypeError:
            raise ValueError("defs values must be iterables of ints in 0..n-1")
        for node in v_iter:
            if not isinstance(node, int) or isinstance(node, bool) or not (0 <= node < n):
                raise ValueError("defs values must be iterables of ints in 0..n-1")

    # Build adjacency and reverse adjacency lists
    adj = [[] for _ in range(n)]
    pred = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        pred[v].append(u)

    # Find reachable nodes via BFS
    reachable = [False] * n
    q = [entry]
    reachable[entry] = True
    head = 0
    while head < len(q):
        u = q[head]
        head += 1
        for v in adj[u]:
            if not reachable[v]:
                reachable[v] = True
                q.append(v)

    # DFS to compute discovery order and parents
    dfs_num = [-1] * n
    dfs_parent = [-1] * n
    dfs_order = []
    stack = [entry]
    while stack:
        u = stack.pop()
        if dfs_num[u] != -1:
            continue
        dfs_num[u] = len(dfs_order)
        dfs_order.append(u)
        for v in adj[u]:
            if dfs_num[v] == -1:
                dfs_parent[v] = u
                stack.append(v)

    # Dominator computation using Cooper et al. algorithm
    semi = list(range(n))
    idom = list(range(n))
    bucket = [[] for _ in range(n)]
    dsu = list(range(n))
    dsu_semi = list(range(n))  # stores node index with min semi in the set

    def find(v):
        root = v
        while dsu[root] != root:
            root = dsu[root]
        while dsu[v] != root:
            nxt = dsu[v]
            dsu[v] = root
            v = nxt
        return root

    def link(p, v):
        dsu[v] = p
        if dfs_num[semi[dsu_semi[v]]] < dfs_num[semi[dsu_semi[p]]]:
            dsu_semi[p] = dsu_semi[v]

    def eval(v):
        root = find(v)
        return dsu_semi[root]

    # Process nodes in reverse DFS order
    for i in range(len(dfs_order) - 1, 0, -1):
        v = dfs_order[i]
        for u in pred[v]:
            if dfs_num[u] != -1:
                a = eval(u)
                if dfs_num[semi[a]] < dfs_num[semi[v]]:
                    semi[v] = a
        bucket[dfs_parent[v]].append(v)
        link(dfs_parent[v], v)
        for w in bucket[dfs_parent[v]]:
            a = eval(w)
            if dfs_num[semi[a]] < dfs_num[semi[w]]:
                idom[w] = a
            else:
                idom[w] = dfs_parent[v]
        bucket[dfs_parent[v]] = []

    # Compute Dominance Frontiers
    # Standard efficient algorithm: for each v, for each pred u != idom[v],
    # walk up the dominator tree from u to idom[v] adding v to DF[w]
    DF = [[] for _ in range(n)]
    for v in dfs_order:
        if v == entry:
            continue
        for u in pred[v]:
            if u == idom[v]:
                continue
            w = u
            while w != idom[v]:
                DF[w].append(v)
                w = idom[w]
                # Safety break if idom chain is broken, though logically shouldn't happen
                if w == -1:
                    break

    # Compute P for each variable
    result = {}
    for var, var_defs in defs.items():
        S = [d for d in var_defs if reachable[d]]
        if not S:
            result[var] = []
            continue

        # P is the closure of DF(S) under DF
        P = set()
        worklist = []
        for d in S:
            for y in DF[d]:
                if y not in P:
                    P.add(y)
                    worklist.append(y)

        while worklist:
            u = worklist.pop()
            for v in DF[u]:
                if v not in P:
                    P.add(v)
                    worklist.append(v)
        result[var] = sorted(P)

    return result

