import sys

def phi_blocks(n, edges, entry, defs):
    # Input validation
    if not isinstance(n, int) or isinstance(n, bool) or n < 1:
        raise ValueError("n must be an int >= 1")
    if not isinstance(entry, int) or isinstance(entry, bool) or not (0 <= entry < n):
        raise ValueError("entry must be an int in 0..n-1")
    if not isinstance(edges, list):
        raise ValueError("edges must be a list")
    for u, v in edges:
        if not (isinstance(u, int) and not isinstance(u, bool) and 0 <= u < n and
                isinstance(v, int) and not isinstance(v, bool) and 0 <= v < n):
            raise ValueError("edges must be a list of pairs of ints in 0..n-1")
    if not isinstance(defs, dict):
        raise ValueError("defs must be a dict")
    for k, vals in defs.items():
        for v in vals:
            if not (isinstance(v, int) and not isinstance(v, bool) and 0 <= v < n):
                raise ValueError("defs values must be iterables of ints in 0..n-1")

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)

    # Find reachable nodes
    reachable = [False] * n
    queue = [entry]
    reachable[entry] = True
    head = 0
    while head < len(queue):
        u = queue[head]
        head += 1
        for v in adj[u]:
            if not reachable[v]:
                reachable[v] = True
                queue.append(v)

    # Lengauer-Tarjan dominator algorithm
    parent = [-1] * n
    semi = list(range(n))
    idom = list(range(n))
    ancestor = [-1] * n
    bucket = [[] for _ in range(n)]
    pre = [-1] * n
    timer = 0
    node_at_pre = [0] * n

    sys.setrecursionlimit(50000)
    def dfs(u):
        nonlocal timer
        timer += 1
        pre[u] = timer
        node_at_pre[timer] = u
        for v in adj[u]:
            if pre[v] == -1:
                parent[v] = u
                dfs(v)
    dfs(entry)

    dsu_parent = list(range(n + 1))
    dsu_semi = list(range(n + 1))

    def eval_node(v):
        if ancestor[parent[v]] == v:
            return semi[v]
        find(parent[v])
        if semi[ancestor[dsu_parent[v]]] < semi[ancestor[v]]:
            ancestor[v] = ancestor[dsu_parent[v]]
        return ancestor[v]

    def find(v):
        if dsu_parent[v] == v:
            return v
        res = find(dsu_parent[v])
        if semi[dsu_semi[dsu_parent[v]]] < semi[dsu_semi[v]]:
            dsu_semi[v] = dsu_semi[dsu_parent[v]]
        dsu_parent[v] = res
        return res

    def link(v, w):
        dsu_parent[v] = w
        dsu_semi[v] = dsu_semi[w]

    # Step 2: Compute semi-dominators
    for i in range(timer, 1, -1):
        w = node_at_pre[i]
        for v in adj[w]:
            if pre[v] != -1:
                u = eval_node(v)
                if semi[u] < semi[w]:
                    semi[w] = u
        bucket[semi[w]].append(w)
        w_par = parent[w]
        if w_par != -1:
            link(w, w_par)
            bucket[w_par].extend(bucket[w])
            bucket[w] = []

    # Step 3: Compute immediate dominators
    for i in range(2, timer + 1):
        w = node_at_pre[i]
        for v in bucket[w]:
            u = eval_node(v)
            if semi[u] == semi[v]:
                idom[v] = w
            else:
                idom[v] = u

    # Step 4: Refine
    for i in range(2, timer + 1):
        w = node_at_pre[i]
        if idom[w] != semi[w]:
            idom[w] = idom[idom[w]]

    # Build dominator tree and compute preorder/postorder times
    dom_adj = [[] for _ in range(n)]
    for v in range(1, n):
        if reachable[v] and idom[v] != v and idom[v] != -1:
            dom_adj[idom[v]].append(v)
    dom_adj[entry] = [v for v in dom_adj[entry] if reachable[v]]

    pre_d = [-1] * n
    post_d = [-1] * n
    timer_d = 0
    def dfs_dom(u):
        nonlocal timer_d
        timer_d += 1
        pre_d[u] = timer_d
        for v in dom_adj[u]:
            if reachable[v]:
                dfs_dom(v)
        post_d[u] = timer_d
    dfs_dom(entry)

    def dominates(x, w):
        if x == w:
            return True
        return pre_d[x] <= pre_d[w] and post_d[x] >= post_d[w]

    # Compute P for each variable
    result = {}
    for var, def_nodes in defs.items():
        S = set(v for v in def_nodes if reachable[v])
        if not S:
            result[var] = []
            continue
        P = set(S)
        worklist = list(S)
        while worklist:
            x = worklist.pop()
            for y in adj[x]:
                if not reachable[y]:
                    continue
                w = y
                while not dominates(x, w):
                    if w not in P:
                        P.add(w)
                        worklist.append(w)
                    if w == entry:
                        break
                    w = idom[w]
        result[var] = sorted(P)
    return result

import sys

def phi_blocks(n, edges, entry, defs):
    # Input validation
    if not isinstance(n, int) or isinstance(n, bool) or n < 1:
        raise ValueError("n must be an int >= 1")
    if not isinstance(entry, int) or isinstance(entry, bool) or not (0 <= entry < n):
        raise ValueError("entry must be an int in 0..n-1")
    if not isinstance(edges, list):
        raise ValueError("edges must be a list")
    for u, v in edges:
        if not (isinstance(u, int) and not isinstance(u, bool) and 0 <= u < n and
                isinstance(v, int) and not isinstance(v, bool) and 0 <= v < n):
            raise ValueError("edges must be a list of pairs of ints in 0..n-1")
    if not isinstance(defs, dict):
        raise ValueError("defs must be a dict")
    for k, vals in defs.items():
        for v in vals:
            if not (isinstance(v, int) and not isinstance(v, bool) and 0 <= v < n):
                raise ValueError("defs values must be iterables of ints in 0..n-1")

    # Build adjacency lists
    adj = [[] for _ in range(n)]
    rev_adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        rev_adj[v].append(u)

    # Find reachable nodes via BFS
    reachable = [False] * n
    queue = [entry]
    reachable[entry] = True
    head = 0
    while head < len(queue):
        u = queue[head]
        head += 1
        for v in adj[u]:
            if not reachable[v]:
                reachable[v] = True
                queue.append(v)

    # Lengauer-Tarjan Dominator Algorithm
    pre = [-1] * n
    post = [-1] * n
    parent = [-1] * n
    node_at_pre = [0] * (n + 1)
    timer = 0

    # Iterative DFS to compute pre, post, parent
    stack = [(entry, 0)]
    pre[entry] = 0
    node_at_pre[0] = entry
    while stack:
        u, idx = stack[-1]
        if idx < len(adj[u]):
            v = adj[u][idx]
            stack[-1] = (u, idx + 1)
            if pre[v] == -1:
                pre[v] = timer
                node_at_pre[timer] = v
                timer += 1
                parent[v] = u
                stack.append((v, 0))
        else:
            post[u] = timer
            stack.pop()

    # Initialize DSU for semi-dominators
    dsu_parent = list(range(n + 1))
    dsu_semi = list(range(n + 1))
    semi = list(range(n))
    idom = list(range(n))
    ancestor = [-1] * n
    bucket = [[] for _ in range(n)]

    def eval_node(v):
        if ancestor[parent[v]] == v:
            return semi[v]
        find(parent[v])
        if semi[ancestor[dsu_parent[v]]] < semi[ancestor[v]]:
            ancestor[v] = ancestor[dsu_parent[v]]
        return ancestor[v]

    def find(v):
        if dsu_parent[v] == v:
            return v
        res = find(dsu_parent[v])
        if semi[dsu_semi[dsu_parent[v]]] < semi[dsu_semi[v]]:
            dsu_semi[v] = dsu_semi[dsu_parent[v]]
        dsu_parent[v] = res
        return res

    def link(v, w):
        dsu_parent[v] = w
        dsu_semi[v] = dsu_semi[w]

    # Step 2: Compute semi-dominators
    for i in range(timer, 1, -1):
        w = node_at_pre[i]
        for v in adj[w]:
            if pre[v] != -1:
                u = eval_node(v)
                if semi[u] < semi[w]:
                    semi[w] = u
        bucket[semi[w]].append(w)
        w_par = parent[w]
        if w_par != -1:
            link(w, w_par)
            bucket[w_par].extend(bucket[w])
            bucket[w] = []

    # Step 3: Compute immediate dominators
    for i in range(2, timer + 1):
        w = node_at_pre[i]
        for v in bucket[w]:
            u = eval_node(v)
            if semi[u] == semi[v]:
                idom[v] = w
            else:
                idom[v] = u

    # Step 4: Refine
    for i in range(2, timer + 1):
        w = node_at_pre[i]
        if idom[w] != semi[w]:
            idom[w] = idom[idom[w]]

    idom[entry] = entry

    # Build dominator tree
    dom_adj = [[] for _ in range(n)]
    for v in range(1, n):
        if reachable[v] and idom[v] != v and idom[v] != -1:
            dom_adj[idom[v]].append(v)
    dom_adj[entry] = [v for v in dom_adj[entry] if reachable[v]]

    # Compute depth and binary lifting table for LCA
    LOG = 16
    up = [[-1] * LOG for _ in range(n)]
    depth = [0] * n

    stack = [(entry, 0)]
    while stack:
        u, idx = stack[-1]
        if idx == 0:
            if u != entry:
                p = idom[u]
                up[u][0] = p
                for i in range(1, LOG):
                    if up[u][i-1] != -1:
                        up[u][i] = up[up[u][i-1]][i-1]
                    else:
                        up[u][i] = -1
                depth[u] = depth[p] + 1
            else:
                up[u][0] = u
                for i in range(1, LOG):
                    up[u][i] = u
        if idx < len(dom_adj[u]):
            v = dom_adj[u][idx]
            stack[-1] = (u, idx + 1)
            stack.append((v, 0))
        else:
            stack.pop()

    def lca(u, v):
        if depth[u] < depth[v]:
            u, v = v, u
        for i in range(LOG - 1, -1, -1):
            if depth[u] - (1 << i) >= depth[v]:
                u = up[u][i]
        if u == v:
            return u
        for i in range(LOG - 1, -1, -1):
            if up[u][i] != up[v][i]:
                u = up[u][i]
                v = up[v][i]
        return up[u][0]

    # Compute Dominance Frontiers
    DF = [set() for _ in range(n)]
    for v in range(n):
        if not reachable[v]:
            continue
        preds = [u for u in rev_adj[v] if reachable[u]]
        if len(preds) > 1:
            preds.sort(key=lambda x: pre[x])
            for i in range(len(preds) - 1):
                w = lca(preds[i], preds[i+1])
                temp = preds[i+1]
                while temp != w:
                    DF[temp].add(v)
                    temp = idom[temp]

    # Compute P for each variable
    result = {}
    for var, def_nodes in defs.items():
        S = set(v for v in def_nodes if reachable[v])
        if not S:
            result[var] = []
            continue
        P = set(S)
        worklist = list(S)
        while worklist:
            x = worklist.pop()
            for y in DF[x]:
                if y not in P:
                    P.add(y)
                    worklist.append(y)
        result[var] = sorted(P)
    return result

import sys

def phi_blocks(n, edges, entry, defs):
    # Input validation
    if not isinstance(n, int) or isinstance(n, bool) or n < 1:
        raise ValueError("n must be an int >= 1")
    if not isinstance(entry, int) or isinstance(entry, bool) or not (0 <= entry < n):
        raise ValueError("entry must be an int in 0..n-1")
    if not isinstance(edges, list):
        raise ValueError("edges must be a list")
    for u, v in edges:
        if not (isinstance(u, int) and not isinstance(u, bool) and 0 <= u < n and
                isinstance(v, int) and not isinstance(v, bool) and 0 <= v < n):
            raise ValueError("edges must be a list of pairs of ints in 0..n-1")
    if not isinstance(defs, dict):
        raise ValueError("defs must be a dict")
    for k, vals in defs.items():
        for v in vals:
            if not (isinstance(v, int) and not isinstance(v, bool) and 0 <= v < n):
                raise ValueError("defs values must be iterables of ints in 0..n-1")

    sys.setrecursionlimit(50000)

    adj = [[] for _ in range(n)]
    rev_adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        rev_adj[v].append(u)

    # Find reachable nodes
    reachable = [False] * n
    queue = [entry]
    reachable[entry] = True
    head = 0
    while head < len(queue):
        u = queue[head]
        head += 1
        for v in adj[u]:
            if not reachable[v]:
                reachable[v] = True
                queue.append(v)

    # Iterative DFS to compute pre-order, parent pointers
    pre = [-1] * n
    parent = [-1] * n
    node_at_pre = [0] * n
    timer = 0
    stack = [(entry, 0)]
    pre[entry] = timer
    node_at_pre[timer] = entry
    timer += 1
    while stack:
        u, idx = stack[-1]
        if idx < len(adj[u]):
            v = adj[u][idx]
            stack[-1] = (u, idx + 1)
            if pre[v] == -1:
                pre[v] = timer
                node_at_pre[timer] = v
                timer += 1
                parent[v] = u
                stack.append((v, 0))
        else:
            stack.pop()

    num = timer
    # DSU structures indexed by pre-number
    dsu_p = list(range(num))
    dsu_s = list(range(num))
    semi = list(range(num))
    idom = list(range(num))
    ancestor = [-1] * num
    bucket = [[] for _ in range(num)]

    def eval_node(v):
        if ancestor[dsu_p[v]] == v:
            return semi[dsu_p[v]]
        find_node(v)
        if semi[dsu_s[dsu_p[v]]] < semi[dsu_s[v]]:
            ancestor[v] = ancestor[dsu_p[v]]
        return ancestor[v]

    def find_node(v):
        if dsu_p[v] == v:
            return v
        res = find_node(dsu_p[v])
        if semi[dsu_s[dsu_p[v]]] < semi[dsu_s[v]]:
            dsu_s[v] = dsu_s[dsu_p[v]]
        dsu_p[v] = res
        return res

    def link(v, w):
        dsu_p[v] = w
        dsu_s[v] = dsu_s[w]

    # Step 2: Compute semi-dominators
    for i in range(num - 1, 0, -1):
        w = node_at_pre[i]
        for v in adj[w]:
            if pre[v] != -1:
                u = eval_node(pre[v])
                if semi[u] < semi[i]:
                    semi[i] = semi[u]
        bucket[semi[i]].append(i)
        w_par = parent[w]
        if w_par != -1:
            link(pre[w], pre[w_par])
            bucket[semi[w_par]].extend(bucket[semi[i]])
            bucket[semi[i]] = []

    # Step 3: Compute immediate dominators
    for i in range(1, num):
        w = node_at_pre[i]
        for v in bucket[i]:
            u = eval_node(v)
            if semi[u] == semi[v]:
                idom[v] = w
            else:
                idom[v] = node_at_pre[semi[u]]

    # Step 4: Refine
    for i in range(1, num):
        w = node_at_pre[i]
        if idom[w] != node_at_pre[semi[i]]:
            idom[w] = idom[idom[w]]

    idom[entry] = entry

    # Build dominator tree adjacency list
    dom_adj = [[] for _ in range(n)]
    for v in range(n):
        if reachable[v] and v != entry:
            p = idom[v]
            if p != -1 and p != v:
                dom_adj[p].append(v)
    dom_adj[entry] = [v for v in dom_adj[entry] if reachable[v]]

    # Binary lifting for LCA
    LOG = 16
    up = [[-1] * LOG for _ in range(n)]
    depth = [0] * n

    stack = [(entry, 0)]
    while stack:
        u, idx = stack[-1]
        if idx == 0:
            if u != entry:
                p = idom[u]
                up[u][0] = p
                for i in range(1, LOG):
                    if up[u][i-1] != -1:
                        up[u][i] = up[up[u][i-1]][i-1]
                    else:
                        up[u][i] = -1
                depth[u] = depth[p] + 1
            else:
                up[u][0] = u
                for i in range(1, LOG):
                    up[u][i] = u
        if idx < len(dom_adj[u]):
            v = dom_adj[u][idx]
            stack[-1] = (u, idx + 1)
            stack.append((v, 0))
        else:
            stack.pop()

    def lca(u, v):
        if depth[u] < depth[v]:
            u, v = v, u
        for i in range(LOG - 1, -1, -1):
            if depth[u] - (1 << i) >= depth[v]:
                u = up[u][i]
        if u == v:
            return u
        for i in range(LOG - 1, -1, -1):
            if up[u][i] != up[v][i]:
                u = up[u][i]
                v = up[v][i]
        return up[u][0]

    # Compute Dominance Frontiers
    DF = [set() for _ in range(n)]
    for v in range(n):
        if not reachable[v]:
            continue
        preds = [u for u in rev_adj[v] if reachable[u]]
        if len(preds) > 1:
            preds.sort(key=lambda x: pre[x])
            for i in range(len(preds) - 1):
                w = lca(preds[i], preds[i+1])
                temp = preds[i+1]
                while temp != w:
                    DF[temp].add(v)
                    temp = idom[temp]

    # Compute P for each variable
    result = {}
    for var, def_nodes in defs.items():
        S = set(v for v in def_nodes if reachable[v])
        if not S:
            result[var] = []
            continue
        P = set(S)
        worklist = list(S)
        while worklist:
            x = worklist.pop()
            for y in DF[x]:
                if y not in P:
                    P.add(y)
                    worklist.append(y)
        result[var] = sorted(P)
    return result

import sys

def round_dec(s, places, mode):
    if not isinstance(s, str):
        raise ValueError("s must be a string")
    if isinstance(places, bool) or not isinstance(places, int):
        raise ValueError("places must be an int")
    if not isinstance(mode, str) or mode not in ("half_even", "half_up", "half_down", "floor", "ceil", "up", "down"):
        raise ValueError("Invalid mode")
    if not (-10**6 <= places <= 10**6):
        raise ValueError("places out of range")

    # Parse exponent
    ei = -1
    for i, c in enumerate(s):
        if c in 'eE':
            if ei != -1: raise ValueError("Invalid s")
            ei = i
    if ei != -1:
        exp_str = s[ei+1:]
        digits_part = exp_str.lstrip('+-')
        if not digits_part.isdigit() or not (1 <= len(digits_part) <= 10):
            raise ValueError("Invalid exponent")
        exp = int(exp_str)
        m_str = s[:ei]
    else:
        exp = 0
        m_str = s

    # Parse mantissa
    dot_idx = m_str.find('.')
    if m_str.count('.') > 1:
        raise ValueError("Invalid s")
    if dot_idx != -1:
        int_p = m_str[:dot_idx]
        frac_p = m_str[dot_idx+1:]
    else:
        int_p = m_str
        frac_p = ""

    if not int_p and not frac_p:
        raise ValueError("At least one digit required")
    if int_p and not int_p.isdigit():
        raise ValueError("Invalid digits")
    if frac_p and not frac_p.isdigit():
        raise ValueError("Invalid digits")

    # Extract sign and digits
    sign_val = 1
    digits = int_p + frac_p
    if digits.startswith('+'):
        digits = digits[1:]
    elif digits.startswith('-'):
        sign_val = -1
        digits = digits[1:]
    if not digits or not digits.isdigit():
        raise ValueError("At least one digit required")

    M = int(digits)
    E = exp - len(frac_p)
    P = places
    shift = E + P

    # Rounding logic
    R_abs = 0
    if shift >= 0:
        # Exact multiple, no rounding needed
        # Check size early to avoid creating huge integers
        est_digits = len(digits) + shift
        if est_digits > 4005:
            raise ValueError("Output exceeds 4000 digits")
        R_abs = M * (10 ** shift)
    else:
        k = -shift
        M_len = len(digits)
        if k >= M_len + 2:
            q, r = 0, M
        else:
            divisor = 10**k
            q, r = divmod(M, divisor)

        base = q
        half = divisor // 2

        if r < half:
            R_abs = base
        elif r > half:
            R_abs = base + 1
        else:
            # Tie
            c1 = base
            c2 = base + 1
            if mode == "half_even":
                R_abs = c1 if c1 % 2 == 0 else c2
            elif mode in ("half_up", "ceil", "up"):
                R_abs = c2
            else: # half_down, floor, down
                R_abs = c1

    # Size check
    if P <= 0:
        # Output is R_abs followed by -P zeros
        digits_count = len(str(R_abs)) - P
    else:
        # Output is integer part and P fractional digits
        int_part_len = len(str(R_abs // (10**P)))
        digits_count = int_part_len + P

    if digits_count > 4000:
        raise ValueError("Output exceeds 4000 digits")

    # Format output
    if P <= 0:
        val = R_abs * (10 ** (-P))
        s_out = str(val)
        if sign_val == -1 and val != 0:
            s_out = "-" + s_out
    else:
        int_part = R_abs // (10**P)
        frac_part = R_abs % (10**P)
        s_int = str(int_part)
        s_frac = str(frac_part).zfill(P)
        s_out = s_int + "." + s_frac
        if sign_val == -1 and (int_part != 0 or frac_part != 0):
            s_out = "-" + s_out

    return s_out

def round_dec(s, places, mode):
    valid_modes = {"half_even", "half_up", "half_down", "floor", "ceil", "up", "down"}

    if not isinstance(s, str):
        raise ValueError
    if mode not in valid_modes:
        raise ValueError
    if not isinstance(places, int) or isinstance(places, bool):
        raise ValueError
    if not (-10**6 <= places <= 10**6):
        raise ValueError

    # Parse sign
    sign = 1
    if s.startswith('+'):
        s = s[1:]
    elif s.startswith('-'):
        sign = -1
        s = s[1:]

    # Split exponent
    e_idx = s.find('e')
    if e_idx == -1:
        e_idx = s.find('E')

    if e_idx != -1:
        exp_str = s[e_idx+1:]
        if not exp_str:
            raise ValueError
        if exp_str[0] in '+-':
            if len(exp_str) > 11 or not exp_str[1:].isdigit():
                raise ValueError
        else:
            if len(exp_str) > 10 or not exp_str.isdigit():
                raise ValueError
        exp_val = int(exp_str)
        mantissa = s[:e_idx]
    else:
        mantissa = s
        exp_val = 0

    # Parse mantissa
    if '.' in mantissa:
        dot = mantissa.index('.')
        int_p = mantissa[:dot]
        frac_p = mantissa[dot+1:]
        if not int_p and not frac_p:
            raise ValueError
    else:
        int_p = mantissa
        frac_p = ""

    if not int_p.isdigit() or not frac_p.isdigit():
        raise ValueError
    if not int_p and not frac_p:
        raise ValueError

    d = int(int_p + frac_p)
    k_frac = len(frac_p)
    E_total = k_frac + exp_val

    # Size check before heavy computation
    if E_total + places > 4000 or places > 4000:
        raise ValueError

    # Handle zero
    if d == 0:
        if places > 0:
            return f"0.{'0' * places}"
        return "0"

    # Rounding logic
    M = -(E_total + places)
    if M <= 0:
        # No fractional part to cut off, just shift
        k = d * (10 ** (-M))
    else:
        divisor = 10 ** M
        base = d // divisor
        rem = d % divisor
        half = 5 * (10 ** (M - 1))

        if mode in ("floor", "down"):
            if sign == 1:
                k = base
            else:
                k = -(base + (1 if rem > 0 else 0))
        elif mode in ("ceil", "up"):
            if sign == 1:
                k = base + (1 if rem > 0 else 0)
            else:
                k = -base
        else:
            # Nearest modes
            if rem < half:
                k = base
            elif rem > half:
                k = base + 1
            else:
                # Tie
                if mode == "half_even":
                    k = base + (base % 2)
                elif mode == "half_up":
                    k = base + 1
                else: # half_down
                    k = base
            k *= sign

    # Format output
    if places > 0:
        int_part = str(abs(k) // (10 ** places))
        frac_part = str(abs(k) % (10 ** places)).zfill(places)
        res = f"{int_part}.{frac_part}"
    else:
        shift = -places
        res = str(abs(k)) + "0" * shift

    if len(res) > 4000:
        raise ValueError

    return res if sign == 1 or int(res) != 0 else res.lstrip('-') or "0"

import datetime
import bisect

def _validate_leaps(leaps):
    if not isinstance(leaps, (list, tuple)):
        raise ValueError("leaps must be list or tuple")
    if len(leaps) > 200:
        raise ValueError("leaps has too many entries")
    prev_ym = (0, 0)
    for entry in leaps:
        if not isinstance(entry, (list, tuple)) or len(entry) != 3:
            raise ValueError("Each leap entry must be a list/tuple of 3 ints")
        y, m, d = entry
        if type(y) is not int or type(m) is not int or type(d) is not int:
            raise ValueError("Leap entries must contain ints")
        if not (1970 <= y <= 9998):
            raise ValueError("Year out of range")
        if not (1 <= m <= 12):
            raise ValueError("Month out of range")
        if d not in (1, -1):
            raise ValueError("Delta must be 1 or -1")
        if (y, m) <= prev_ym:
            raise ValueError("Leaps must be strictly increasing")
        prev_ym = (y, m)

def _precompute(leaps):
    base = datetime.date(1970, 1, 1)
    base_ord = base.toordinal()

    leap_dates = []
    leap_deltas = []

    for y, m, delta in leaps:
        if m in (1, 3, 5, 7, 8, 10, 12):
            d = 31
        elif m in (4, 6, 9, 11):
            d = 30
        else:
            d = 29 if (y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)) else 28
        leap_dates.append(datetime.date(y, m, d))
        leap_deltas.append(delta)

    cum_offsets = [0]
    for delta in leap_deltas:
        cum_offsets.append(cum_offsets[-1] + delta)

    leap_set = set(leap_dates)
    leap_dict = dict(zip(leap_dates, leap_deltas))

    return base, base_ord, leap_dates, leap_deltas, cum_offsets, leap_set, leap_dict

def _seconds_from_epoch(d, base_ord, leap_dates, cum_offsets):
    idx = bisect.bisect_left(leap_dates, d)
    offset = cum_offsets[idx]
    days = d.toordinal() - base_ord
    return days * 86400 + offset

def _day_length(d, leap_dict):
    return 86400 + leap_dict.get(d, 0)

def leap_label(n, leaps):
    if type(n) is not int or isinstance(n, bool):
        raise ValueError("n must be int >= 0")
    if n < 0:
        raise ValueError("n must be >= 0")
    _validate_leaps(leaps)

    base, base_ord, leap_dates, _, cum_offsets, leap_dict, _ = _precompute(leaps)

    approx_days = n // 86400
    d = base + datetime.timedelta(days=approx_days)

    while True:
        sec_start = _seconds_from_epoch(d, base_ord, leap_dates, cum_offsets)
        day_len = _day_length(d, leap_dict)

        if n < sec_start:
            d -= datetime.timedelta(days=1)
        elif n >= sec_start + day_len:
            d += datetime.timedelta(days=1)
        else:
            break

        if d.year > 9999:
            raise ValueError("Year exceeds 9999")
        if d.year < 1970:
            raise ValueError("Date before 1970")

    time_sec = n - sec_start
    h = time_sec // 3600
    rem = time_sec % 3600
    m = rem // 60
    s = rem % 60

    return f"{d.year:04d}-{d.month:02d}-{d.day:02d} {h:02d}:{m:02d}:{s:02d}"

def leap_count(label, leaps):
    if not isinstance(label, str) or len(label) != 19:
        raise ValueError("Invalid label format")
    if label[4] != '-' or label[7] != '-' or label[10] != ' ' or label[13] != ':' or label[16] != ':':
        raise ValueError("Invalid label format")
    for i in range(19):
        if i in (4, 7, 10, 13, 16):
            continue
        if not label[i].isdigit():
            raise ValueError("Invalid label format")

    y = int(label[0:4])
    m = int(label[5:7])
    d = int(label[8:10])
    h = int(label[11:13])
    mi = int(label[14:16])
    s = int(label[17:19])

    if not (1970 <= y <= 9999):
        raise ValueError("Year out of range")
    if not (1 <= m <= 12):
        raise ValueError("Month out of range")

    if m in (1, 3, 5, 7, 8, 10, 12):
        dim = 31
    elif m in (4, 6, 9, 11):
        dim = 30
    else:
        dim = 29 if (y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)) else 28

    if not (1 <= d <= dim):
        raise ValueError("Day out of range")
    if not (0 <= h <= 23):
        raise ValueError("Hour out of range")
    if not (0 <= mi <= 59):
        raise ValueError("Minute out of range")
    if not (0 <= s <= 60):
        raise ValueError("Second out of range")

    _validate_leaps(leaps)
    base, base_ord, leap_dates, _, cum_offsets, leap_set, leap_dict = _precompute(leaps)

    date_obj = datetime.date(y, m, d)

    day_len = _day_length(date_obj, leap_dict)
    time_sec = h * 3600 + mi * 60 + s

    # Enforce strict second rules
    if s == 60:
        if h != 23 or mi != 59:
            raise ValueError("Second 60 only allowed for 23:59:60")
        if date_obj not in leap_set or leap_dict.get(date_obj) != 1:
            raise ValueError("Second 60 only allowed on +1 leap days")

    if time_sec >= day_len:
