    if not (0 <= s <= 60):
        raise ValueError("Second out of range")

    _validate_leaps(leaps)

    # Validate leap second constraints
    if s == 60:
        if not (h == 23 and mi == 59):
            raise ValueError("ss=60 allowed only for 23:59:60")
        # Check if this day actually has a +1 leap second
        if (y, m) not in leaps or leaps[[i for i, x in enumerate(leaps) if x[0]==y and x[1]==m][0]][2] != 1:
             # Check if (y,m) is in leaps with delta 1
             found = False
             for ly, lm, delta in leaps:
                 if ly == y and lm == m:
                     if delta == 1:
                         found = True
                     break
             if not found:
                 raise ValueError("Label 23:59:60 not valid for this date")

    # Calculate day length
    length = 86400
    if (y, m) in leaps:
        delta = leaps[[i for i, x in enumerate(leaps) if x[0]==y and x[1]==m][0]][2]
        length += delta

    time_sec = h * 3600 + mi * 60 + s

    if time_sec >= length:
        raise ValueError("Label does not exist on its day")

    days = (datetime.date(y, m, d) - datetime.date(1970, 1, 1)).days
    offset = 0
    for ly, lm, delta in leaps:
        if (ly, lm) < (y, m):
            offset += delta
        elif (ly, lm) > (y, m):
            break

    n = days * 86400 + offset + time_sec
    return n

import datetime

def _validate_leaps(leaps):
    if not isinstance(leaps, (list, tuple)):
        raise ValueError("leaps must be list or tuple")
    if len(leaps) > 200:
        raise ValueError("leaps has too many entries")
    prev_ym = (0, 0)
    for entry in leaps:
        if not isinstance(entry, (list, tuple)) or len(entry) != 3:
            raise ValueError("Each leap entry must be a list/tuple of 3 ints")
        y, m, delta = entry
        if type(y) is not int or type(m) is not int or type(delta) is not int:
            raise ValueError("Leap entries must contain ints")
        if not (1970 <= y <= 9998):
            raise ValueError("Year out of range")
        if not (1 <= m <= 12):
            raise ValueError("Month out of range")
        if delta not in (1, -1):
            raise ValueError("Delta must be 1 or -1")
        if (y, m) <= prev_ym:
            raise ValueError("Leaps must be strictly increasing")
        prev_ym = (y, m)

def _days_in_month(y, m):
    if m in (1, 3, 5, 7, 8, 10, 12):
        return 31
    elif m in (4, 6, 9, 11):
        return 30
    else:
        # February
        if (y % 4 == 0 and y % 100 != 0) or (y % 400 == 0):
            return 29
        return 28

def _get_offset(leaps, y, m):
    # Calculates cumulative delta for all leap months strictly before (y, m)
    # leaps is sorted by (year, month)
    offset = 0
    for ly, lm, delta in leaps:
        if (ly, lm) < (y, m):
            offset += delta
        elif (ly, lm) > (y, m):
            break
        # If (ly, lm) == (y, m), the leap is in the current month.
        # The leap second is at the end of the month, so it hasn't passed the start of the day.
        # So we don't include it in the offset for the start of the day.
    return offset

def leap_label(n, leaps):
    if type(n) is not int or isinstance(n, bool):
        raise ValueError("n must be int >= 0")
    if n < 0:
        raise ValueError("n must be >= 0")
    _validate_leaps(leaps)

    # Build a quick lookup for leap months
    leap_map = {}
    for y, m, delta in leaps:
        leap_map[(y, m)] = delta

    # Estimate days
    est_days = n // 86400

    # Convert to date
    try:
        est_date = datetime.date(1970, 1, 1) + datetime.timedelta(days=est_days)
    except OverflowError:
        raise ValueError("Year exceeds 9999")

    if est_date.year > 9999:
        raise ValueError("Year exceeds 9999")

    # Adjust date to find the correct day
    # We loop because the estimate might be off by a few days due to leap seconds
    while True:
        y, m, d = est_date.year, est_date.month, est_date.day

        # Calculate start of day in seconds
        days_from_epoch = (est_date - datetime.date(1970, 1, 1)).days
        offset = _get_offset(leaps, y, m)
        start_sec = days_from_epoch * 86400 + offset

        # Determine length of current day
        length = 86400
        if (y, m) in leap_map:
            length += leap_map[(y, m)]

        # Check if n is within this day
        if start_sec <= n < start_sec + length:
            break
        elif n < start_sec:
            # n is before this day, go back
            est_date -= datetime.timedelta(days=1)
            if est_date.year < 1970:
                raise ValueError("Date before 1970")
        else:
            # n is after this day, go forward
            est_date += datetime.timedelta(days=1)
            if est_date.year > 9999:
                raise ValueError("Year exceeds 9999")

    time_sec = n - start_sec

    # Convert time_sec to hh:mm:ss
    # time_sec is in range [0, length-1]
    # If length is 86401 (leap +1), max time_sec is 86400.
    # 86400 seconds corresponds to 23:59:60.
    if time_sec == 86400:
        h, mi, s = 23, 59, 60
    else:
        h = time_sec // 3600
        rem = time_sec % 3600
        mi = rem // 60
        s = rem % 60

    return f"{y:04d}-{m:02d}-{d:02d} {h:02d}:{mi:02d}:{s:02d}"

def leap_count(label, leaps):
    if not isinstance(label, str) or len(label) != 19:
        raise ValueError("Invalid label format")
    if label[4] != '-' or label[7] != '-' or label[10] != ' ' or label[13] != ':' or label[16] != ':':
        raise ValueError("Invalid label format")
    for i in range(19):
        if i in (4, 7, 10, 13, 16):
            continue
        if not label[i].isdigit():
            raise ValueError("Invalid label format")

    y = int(label[0:4])
    m = int(label[5:7])
    d = int(label[8:10])
    h = int(label[11:13])
    mi = int(label[14:16])
    s = int(label[17:19])

    if not (1970 <= y <= 9999):
        raise ValueError("Year out of range")
    if not (1 <= m <= 12):
        raise ValueError("Month out of range")

    # Validate day
    try:
        datetime.date(y, m, d)
    except ValueError:
        raise ValueError("Day out of range")

    if not (0 <= h <= 23):
        raise ValueError("Hour out of range")
    if not (0 <= mi <= 59):
        raise ValueError("Minute out of range")
    if not (0 <= s <= 60):
        raise ValueError("Second out of range")

    _validate_leaps(leaps)

    # Build leap map for validation
    leap_map = {}
    for ly, lm, delta in leaps:
        leap_map[(ly, lm)] = delta

    # Validate leap second constraints
    if s == 60:
        if not (h == 23 and mi == 59):
            raise ValueError("ss=60 allowed only for 23:59:60")
        # Check if this day actually has a +1 leap second
        if (y, m) not in leap_map or leap_map[(y, m)] != 1:
             raise ValueError("Label 23:59:60 not valid for this date")

    # Check if label is invalid on a -1 leap day (23:59:59 doesn't exist)
    if s == 59 and mi == 59 and h == 23:
        if (y, m) in leap_map and leap_map[(y, m)] == -1:
             raise ValueError("Label 23:59:59 not valid on a -1 leap day")

    # Calculate day length to ensure label exists
    length = 86400
    if (y, m) in leap_map:
        length += leap_map[(y, m)]

    time_sec = h * 3600 + mi * 60 + s
    if time_sec >= length:
        raise ValueError("Label does not exist on its day")

    days = (datetime.date(y, m, d) - datetime.date(1970, 1, 1)).days
    offset = _get_offset(leaps, y, m)

    n = days * 86400 + offset + time_sec
    return n

def list_schedule(jobs, workers):
    # --- Validation ---
    if not isinstance(workers, int) or isinstance(workers, bool) or not (1 <= workers <= 64):
        raise ValueError("Invalid workers")
    if not isinstance(jobs, (list, tuple)):
        raise ValueError("Invalid jobs type")
    if len(jobs) > 200:
        raise ValueError("Too many jobs")

    job_data = {}
    names = set()

    # First pass: collect names, check basic types and structure
    for job in jobs:
        if not isinstance(job, (tuple, list)) or len(job) != 3:
            raise ValueError("Invalid job format")
        name, duration, deps = job
        if not isinstance(name, str) or not name:
            raise ValueError("Invalid job name")
        names.add(name)

        if not isinstance(duration, int) or isinstance(duration, bool):
            raise ValueError("Invalid duration type")
        if not (0 <= duration <= 10**12):
            raise ValueError("Invalid duration range")

        if not isinstance(deps, (list, tuple)):
            raise ValueError("Invalid deps type")
        for d in deps:
            if not isinstance(d, str):
                raise ValueError("Dep is not a string")

        job_data[name] = (duration, deps)

    if len(names) != len(job_data):
        raise ValueError("Duplicate job name")

    # Second pass: check deps existence, self-deps, repeated deps
    adj = {}
    for name, (dur, deps) in job_data.items():
        if len(set(deps)) != len(deps):
            raise ValueError("Repeated dependencies")
        for d in deps:
            if d not in names:
                raise ValueError("Unknown dependency")
            if d == name:
                raise ValueError("Self-dependency")
        adj[name] = deps

    # Cycle detection
    visited = set()
    rec_stack = set()
    def dfs_cycle(node):
        visited.add(node)
        rec_stack.add(node)
        for dep in adj[node]:
            if dep not in visited:
                if dfs_cycle(dep):
                    return True
            elif dep in rec_stack:
                return True
        rec_stack.remove(node)
        return False
    for name in names:
        if name not in visited:
            if dfs_cycle(name):
                raise ValueError("Dependency cycle")

    # --- Priority Calculation ---
    # forward_deps[j] contains jobs that depend on j
    forward_deps = {name: [] for name in names}
    for name, (_, deps) in job_data.items():
        for d in deps:
            forward_deps[d].append(name)

    priority = {}
    def calc_priority(j):
        if j in priority:
            return priority[j]
        max_succ = 0
        for s in forward_deps[j]:
            max_succ = max(max_succ, calc_priority(s))
        priority[j] = job_data[j][0] + max_succ
        return priority[j]

    for j in names:
        calc_priority(j)

    # --- Simulation ---
    if not names:
        return {"start": {}, "worker": {}, "makespan": 0}

    remaining_deps = {j: len(job_data[j][1]) for j in names}
    ready_jobs = [j for j in names if remaining_deps[j] == 0]
    running = {}  # worker -> (job_name, finish_time)
    start_times = {}
    worker_map = {}
    time = 0

    while len(start_times) < len(names):
        # Finish jobs that complete at current time
        finish_now = [(w, j) for w, (j, ft) in running.items() if ft == time]
        for w, j in finish_now:
            del running[w]
            for dep in forward_deps[j]:
                remaining_deps[dep] -= 1
                if remaining_deps[dep] == 0:
                    ready_jobs.append(dep)

        # Sort ready jobs by priority (desc), then name (asc)
        ready_jobs.sort(key=lambda j: (-priority[j], j))

        # Assign ready jobs to lowest-numbered idle workers
        idle_workers = sorted(set(range(workers)) - set(running.keys()))
        while ready_jobs and idle_workers:
            j = ready_jobs.pop(0)
            w = idle_workers[0]  # Peek instead of pop to handle zero-duration jobs correctly
            dur = job_data[j][0]

            start_times[j] = time
            worker_map[j] = w

            if dur == 0:
                # Zero-duration jobs finish immediately, freeing the worker instantly
                for dep in forward_deps[j]:
                    remaining_deps[dep] -= 1
                    if remaining_deps[dep] == 0:
                        ready_jobs.append(dep)
                # Re-sort to account for newly ready jobs at the same time instant
                ready_jobs.sort(key=lambda j: (-priority[j], j))
                # Worker remains idle, idle_workers list is unchanged
            else:
                running[w] = (j, time + dur)
                # Remove used worker and recalculate idle workers
                idle_workers.pop(0)
                idle_workers = sorted(set(range(workers)) - set(running.keys()))

        # Advance time to next event
        if running:
            time = min(ft for _, ft in running.values())
        else:
            break

    makespan = max(start_times[j] + job_data[j][0] for j in start_times)
    return {"start": start_times, "worker": worker_map, "makespan": makespan}

