def list_schedule(jobs, workers):
    # Validate workers
    if not isinstance(workers, int) or isinstance(workers, bool) or not (1 <= workers <= 64):
        raise ValueError("Invalid workers")

    # Validate jobs
    if not isinstance(jobs, (list, tuple)):
        raise ValueError("Invalid jobs")
    if len(jobs) > 200:
        raise ValueError("Too many jobs")

    job_names = set()
    job_data = {}

    for item in jobs:
        if not isinstance(item, (list, tuple)) or len(item) != 3:
            raise ValueError("Invalid job tuple")
        name, duration, deps = item
        if not isinstance(name, str) or not name:
            raise ValueError("Invalid job name")
        if name in job_names:
            raise ValueError("Duplicate job name")
        if not isinstance(duration, int) or isinstance(duration, bool):
            raise ValueError("Invalid duration type")
        if not (0 <= duration <= 10**12):
            raise ValueError("Invalid duration value")
        if not isinstance(deps, (list, tuple)):
            raise ValueError("Invalid deps type")
        if len(deps) != len(set(deps)):
            raise ValueError("Repeated dep in same job")
        for d in deps:
            if not isinstance(d, str):
                raise ValueError("Invalid dep name type")
        job_names.add(name)
        job_data[name] = (duration, list(deps))

    # Check deps exist and no self-deps
    for name, (dur, deps) in job_data.items():
        for d in deps:
            if d not in job_names:
                raise ValueError(f"Unknown dep {d}")
            if d == name:
                raise ValueError("Self dependency")

    # Build graph and check cycles
    dependents = {n: [] for n in job_names}
    in_degree = {n: 0 for n in job_names}
    for name, (dur, deps) in job_data.items():
        in_degree[name] = len(deps)
        for d in deps:
            dependents[d].append(name)

    # Kahn's for cycle detection
    queue = [n for n in job_names if in_degree[n] == 0]
    visited_count = 0
    q_idx = 0
    while q_idx < len(queue):
        u = queue[q_idx]
        q_idx += 1
        visited_count += 1
        for v in dependents[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)
    if visited_count != len(job_names):
        raise ValueError("Dependency cycle")

    # Compute priorities
    memo = {}
    def get_priority(j):
        if j in memo:
            return memo[j]
        max_dep_priority = 0
        for dep_job in dependents[j]:
            max_dep_priority = max(max_dep_priority, get_priority(dep_job))
        res = job_data[j][0] + max_dep_priority
        memo[j] = res
        return res

    priorities = {n: get_priority(n) for n in job_names}

    # Simulation
    if not job_names:
        return {"start": {}, "worker": {}, "makespan": 0}

    start_times = {}
    worker_assignments = {}
    time = 0
    free_workers = set(range(workers))
    busy_workers = {} # wid -> (finish_time, job_name)
    makespan = 0

    remaining_deps = {n: len(job_data[n][1]) for n in job_names}
    ready_jobs = {n for n in job_names if remaining_deps[n] == 0}

    while ready_jobs or busy_workers:
        # Process completions at current time
        if busy_workers:
            finishing = []
            new_busy = {}
            for wid, (ft, jname) in busy_workers.items():
                if ft == time:
                    finishing.append((wid, jname))
                else:
                    new_busy[wid] = (ft, jname)
            busy_workers = new_busy

            for wid, jname in finishing:
                free_workers.add(wid)
                for dep_job in dependents[jname]:
                    remaining_deps[dep_job] -= 1
                    if remaining_deps[dep_job] == 0:
                        ready_jobs.add(dep_job)
                makespan = max(makespan, time)

        # Schedule ready jobs
        if ready_jobs and free_workers:
            sorted_ready = sorted(ready_jobs, key=lambda j: (-priorities[j], j))
            sorted_free = sorted(free_workers)
            count = min(len(sorted_ready), len(sorted_free))

            for i in range(count):
                jname = sorted_ready[i]
                wid = sorted_free[i]
                dur = job_data[jname][0]
                ft = time + dur

                start_times[jname] = time
                worker_assignments[jname] = wid
                free_workers.remove(wid)
                busy_workers[wid] = (ft, jname)
                ready_jobs.remove(jname)

        # Advance time
        if busy_workers:
            next_time = min(ft for ft, _ in busy_workers.values())
            if next_time > time:
                time = next_time
            # else: time stays same, loop continues to process 0-duration jobs or new ready jobs
        else:
            break

    return {"start": start_times, "worker": worker_assignments, "makespan": makespan}

